def find_beautiful_indices(s, a, b, k):
    # KMP: all start indices of pat in text (linear time)
    def find_all(text, pat):
        m = len(pat)
        lps = [0] * m
        j = 0
        for i in range(1, m):
            while j and pat[i] != pat[j]:
                j = lps[j - 1]
            if pat[i] == pat[j]:
                j += 1
            lps[i] = j
        res = []
        j = 0
        for i, ch in enumerate(text):
            while j and ch != pat[j]:
                j = lps[j - 1]
            if ch == pat[j]:
                j += 1
            if j == m:
                res.append(i - m + 1)
                j = lps[j - 1]
        return res

    a_positions = find_all(s, a)
    b_positions = find_all(s, b)  # already sorted

    # If no a or b substrings found, no beautiful indices
    if not a_positions or not b_positions:
        return []

    import bisect
    res = []
    for i in a_positions:
        # Find index range for b: [i-k, i+k]
        left = bisect.bisect_left(b_positions, i - k)
        right = bisect.bisect_right(b_positions, i + k)
        if left < right:
            res.append(i)
    return res
